+fn api_request_without_output_limits() -> ResponsesApiRequest {
+    ResponsesApiRequest {
+        model: "gpt-test".to_string(),
+        instructions: String::new(),
+        input: Vec::new(),
+        tools: None,
+        tool_choice: "auto".to_string(),
