+#[test]
+fn frozen_responses_request_concurrent_clones_share_exactly_one_claim() {
+    let frozen = Arc::new(frozen_request());
+    let barrier = Arc::new(Barrier::new(16));
+    let threads: Vec<_> = (0..16)
+        .map(|_| {
+            let frozen = Arc::clone(&frozen);
+            let barrier = Arc::clone(&barrier);
+            std::thread::spawn(move || {
+                let built = built_request(&frozen);
+                barrier.wait();
+                frozen.claim(&built, frozen.request.response_body_limit_bytes)
+            })
+        })
+        .collect();
+    let results: Vec<_> = threads
+        .into_iter()
+        .map(|thread| thread.join().expect("thread completes"))
+        .collect();
+    assert_eq!(results.iter().filter(|result| result.is_ok()).count(), 1);
+    assert_eq!(
+        results
+            .iter()
+            .filter(|result| **result == Err(FrozenRequestError::AlreadyClaimed))
+            .count(),
+        15
+    );
+}
