+#[tokio::test]
+async fn frozen_responses_request_transport_rejects_mutations_before_any_network_send() {
+    for change in [
+        "method",
+        "url",
+        "headers",
+        "body",
+        "timeout",
+        "response cap",
+        "reserialized bytes",
+    ] {
+        let frozen = Arc::new(frozen_request());
+        let transport = ReqwestTransport::for_frozen_responses_request(Arc::clone(&frozen))
+            .expect("client builds without sending");
+        let mut request = frozen.prepared_request();
+        match change {
+            "method" => request.method = Method::GET,
+            "url" => request.url = "https://changed.invalid/v1/responses".to_string(),
+            "headers" => {
+                request.headers.insert(
+                    http::header::AUTHORIZATION,
+                    http::HeaderValue::from_static("Bearer changed"),
+                );
+            }
+            "body" => {
+                request.body = Some(RequestBody::EncodedJson(
+                    EncodedJsonBody::encode(
+                        &json!({"max_output_tokens":128,"truncation":"disabled"}),
+                    )
+                    .expect("encode mutation"),
+                ))
+            }
+            "timeout" => request.timeout = Some(Duration::from_secs(1)),
+            "response cap" => request.response_body_limit_bytes = Some(1),
+            "reserialized bytes" => {
+                let value: serde_json::Value =
+                    serde_json::from_slice(frozen.body_bytes()).expect("valid original JSON");
+                let body = EncodedJsonBody::encode(&value).expect("reserialize same fields");
+                assert_eq!(body.as_bytes(), frozen.body_bytes());
+                request.body = Some(RequestBody::EncodedJson(body));
+            }
+            _ => unreachable!("closed cases"),
+        }
+        let error = transport
+            .stream(request)
+            .await
+            .err()
+            .expect("must reject before DNS or HTTP");
+        assert!(
+            matches!(error, TransportError::Build(ref message) if message == "CODEX_FROZEN_REQUEST_CHANGED")
+        );
+        let error = transport
+            .clone()
+            .execute(frozen.prepared_request())
+            .await
+            .err()
+            .expect("mismatch burns capability");
+        assert!(
+            matches!(error, TransportError::Build(ref message) if message == "CODEX_NEW_OUTBOUND_CONSENT_REQUIRED")
+        );
+    }
+}
